import{_t as e,it as t,n,rt as r}from"./chunks/framework.BzA9dy5I.js";var i=JSON.parse(`{"title":"Alcance y límites","description":"","frontmatter":{},"headers":[],"relativePath":"referencia/limites.md","filePath":"referencia/limites.md"}`),a={name:`referencia/limites.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="alcance-y-limites" tabindex="-1">Alcance y límites <a class="header-anchor" href="#alcance-y-limites" aria-label="Permalink to “Alcance y límites”">​</a></h1><h2 id="disponible" tabindex="-1">Disponible <a class="header-anchor" href="#disponible" aria-label="Permalink to “Disponible”">​</a></h2><p>Canvas vertical u horizontal, trabajos y pasos, decisiones humanas, entradas y salidas tipadas, logs enviados por el agente, reintentos y revisión del trabajo futuro. Integraciones locales mediante MCP o skill; Desktop incluye su runtime.</p><p>El perfil <code>bpmn-lite</code> admite inicio, fin y compuertas exclusivas, inclusivas y paralelas con divisiones y reuniones estructuradas.</p><h2 id="lo-que-aun-no-hace" tabindex="-1">Lo que aún no hace <a class="header-anchor" href="#lo-que-aun-no-hace" aria-label="Permalink to “Lo que aún no hace”">​</a></h2><ul><li>Despertar de forma universal un chat que terminó su turno. La espera cooperativa puede recibir respuestas durante un turno activo.</li><li>Ejecutar herramientas por sí mismo o interceptar todas las llamadas del agente.</li><li>Importar o exportar BPMN XML ni ofrecer BPMN completo: no hay ciclos, temporizadores, compensaciones ni mensajes entre pools.</li><li>Ofrecer un servicio remoto multiusuario, instalación universal desde una frase o conexión entre equipos.</li><li>Publicar cambios o completar decisiones humanas sin la intervención y autorización correspondientes.</li></ul><h2 id="distribucion-actual" tabindex="-1">Distribución actual <a class="header-anchor" href="#distribucion-actual" aria-label="Permalink to “Distribución actual”">​</a></h2><p>La versión descargable <code>v0.4.0-preview.1</code> incluye paquetes para Mac Apple Silicon, Mac Intel y Windows x64. Los builds y pruebas de runtime se ejecutan en esos sistemas. No equivale a verificar todos los entornos de cada proveedor.</p><p>Los instaladores son de prueba y aún no cuentan con firma/notarización. Los cambios nuevos de <code>main</code>, como los desplegables declarados en el plan, estarán en los siguientes instaladores; la documentación de este sitio sigue <code>main</code>.</p><h2 id="privacidad" tabindex="-1">Privacidad <a class="header-anchor" href="#privacidad" aria-label="Permalink to “Privacidad”">​</a></h2><p>El proceso y sus eventos se guardan en el equipo que ejecuta Hyperion. El proveedor de IA sigue aplicando sus propias condiciones al contenido que recibe. Los logs pueden contener información de tu trabajo: comparte solo lo necesario y nunca credenciales.</p><p>GitHub Pages publica esta documentación estática. No recibe ni ejecuta tus flujos, no hospeda SQLite y no sustituye la aplicación local.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};